function documents(){const records=documentRecords().filter(d=>allowedLocations().some(l=>l.id===d.location.id));shell(`<section class="hero"><div><p class="kicker">CONTROLLED DOCUMENT WORKSPACE</p><h1>Document center.</h1><p class="lede">A unified index for proposals, condition reports, agreements, plans and service records.</p></div><div class="hero-meta"><strong>${records.length}</strong><br>Indexed documents<br><small>Static demonstration library</small></div></section><div class="document-toolbar"><label class="field">Search documents<input id="document-search" type="search" placeholder="Location, document or type"></label><label class="field">Document type<select id="document-filter"><option value="all">All documents</option><option>Proposal</option><option>Condition report</option><option>Plans</option><option>Equipment</option><option>Agreement</option><option>Upcoming</option><option>History</option></select></label></div><section class="document-library" id="document-library">${records.map(d=>`<article class="document-card" data-document-search="${`${d.location.name} ${d.type} ${d.title}`.toLowerCase()}" data-document-type="${d.type}"><div><span class="document-icon ${d.tone}">${d.type.slice(0,2).toUpperCase()}</span><p class="kicker">${d.type}</p><h3>${d.title}</h3><p>${d.location.name} · ${d.date}</p></div><div class="actions"><a class="button primary" href="${d.url}" target="_blank" rel="noopener">View document</a><a class="button" href="${d.url}" download>Download</a></div></article>`).join("")}</section><p class="notice">Static demo notice: published files use public URLs. Real confidential records require server-enforced authentication and private object storage.</p>`,"documents");const search=document.querySelector("#document-search"),filter=document.querySelector("#document-filter"),apply=()=>document.querySelectorAll(".document-card").forEach(card=>card.classList.toggle("hidden",!card.dataset.documentSearch.includes(search.value.toLowerCase())||(filter.value!=="all"&&card.dataset.documentType!==filter.value)));search.oninput=apply;filter.onchange=apply}
function coconutOverview(){return `<section class="location-summary"><article class="score-card"><p class="kicker">PORTFOLIO READINESS</p><strong>92</strong><span>Sample condition score</span><div class="score-track"><i style="width:92%"></i></div></article><article class="panel executive"><span class="badge viewed">Proposal ready</span><h2>Preventive care, clearly documented.</h2><p>Four planned maintenance rounds with proposal-aligned reporting, decision history and service visibility for BMW of Coconut Creek.</p><div class="mini-metrics"><span><b>04</b>Rounds / year</span><span><b>$28,512</b>Portfolio price</span><span><b>20.8%</b>Portfolio savings</span></div></article></section><div class="section-title"><h2>Location command center</h2><span>Demonstration workspace</span></div><section class="feature-grid"><button data-location-tab="equipment"><span>01</span><strong>Equipment</strong><small>Unit registry, operating status and issue reporting</small></button><button data-location-tab="condition"><span>02</span><strong>Condition Reports</strong><small>Asset health, findings and recommended priorities</small></button><button data-location-tab="agreement"><span>03</span><strong>Agreement</strong><small>Exact proposal reference, scope and commercial terms</small></button><button data-location-tab="upcoming"><span>04</span><strong>Upcoming Service</strong><small>Visit window, readiness and planned checklist</small></button><button data-location-tab="history"><span>05</span><strong>Service History</strong><small>Auditable sample timeline and closeout records</small></button></section>`}
function demoDocActions(key,label){return `<div class="document-actions"><button type="button" class="button primary" data-demo-doc="${key}">View ${label}</button><button type="button" class="button" data-demo-open="${key}">Open PDF</button><button type="button" class="button" data-demo-download="${key}">Download</button></div>`}
function coconutEquipment(){const requests=(state.requests||[]).filter(r=>r.locationId==="bmw-coconut-creek");return `<div class="section-title"><h2>Equipment registry</h2><span>${COCONUT_EQUIPMENT.length} sample units · Demo inventory</span></div>${demoDocActions("equipment","equipment PDF")}<section class="equipment-toolbar"><div><p class="kicker">BMW OF COCONUT CREEK</p><h2>Every unit. One service path.</h2><p>Select a unit to report loss of cooling, unusual operation or a service need.</p></div><div class="equipment-summary"><span><b>${COCONUT_EQUIPMENT.length}</b>Units</span><span><b>${COCONUT_EQUIPMENT.filter(x=>x.status==="Operational").length}</b>Operational</span><span><b>${requests.length}</b>Open demo requests</span></div></section><section class="equipment-grid">${COCONUT_EQUIPMENT.map(unit=>`<article class="equipment-card"><header><span class="unit-id">${unit.id}</span><span class="unit-state ${unit.status.toLowerCase()}">${unit.status}</span></header><h3>${unit.name}</h3><p>${unit.type} · ${unit.capacity}</p><dl><div><dt>Location</dt><dd>${unit.name}</dd></div><div><dt>Service record</dt><dd>${unit.lastService}</dd></div></dl><button type="button" class="button ${unit.status==="Priority"?"primary":""}" data-report-unit="${unit.id}">Report an issue</button></article>`).join("")}</section><div class="section-title"><h2>Open requests</h2><span>Stored only in this browser</span></div>${requests.length?`<section class="request-list">${requests.slice().reverse().map(r=>`<article><span class="badge sent">Open demo request</span><div><h3>${r.unitId} · ${r.issue}</h3><p>${r.details||"No additional details provided."}</p><small>${r.priority} priority · ${r.createdAt}</small></div></article>`).join("")}</section>`:`<div class="empty">No issues have been reported for this demo location.</div>`}`}
function coconutCondition(){return `<div class="section-title"><h2>Condition report</h2><span>Sample report · Not an actual inspection</span></div>${demoDocActions("condition","condition report")}<section class="report-hero"><div><p class="kicker">BMW OF COCONUT CREEK</p><h2>Operational readiness</h2><p>Demonstration condition snapshot designed to show the reporting standard included with the maintenance program.</p></div><div class="health-ring"><strong>92</strong><span>Sample score</span></div></section><section class="condition-grid"><article class="condition-card good"><span>Airflow</span><strong>Ready</strong><p>Sample: supply and return pathways recorded as clear.</p></article><article class="condition-card good"><span>Electrical</span><strong>Stable</strong><p>Sample: connections and contactors included in inspection scope.</p></article><article class="condition-card watch"><span>Drainage</span><strong>Monitor</strong><p>Sample: condensate treatment scheduled during the first round.</p></article><article class="condition-card good"><span>Controls</span><strong>Online</strong><p>Sample: thermostat response and setpoints included in verification.</p></article></section><section class="panel checklist"><h3>First-round field checklist</h3><div><span>✓ Replace or document filter condition</span><span>✓ Clear and treat condensate lines</span><span>✓ Record refrigerant operating data</span><span>✓ Inspect belts, bearings and electrical connections</span><span>✓ Photograph priority findings</span><span>✓ Deliver executive closeout summary</span></div></section>`}
function coconutAgreement(){return `<div class="section-title"><h2>Agreement workspace</h2><span>Aligned to proposal OB-PM-2026-1008-01</span></div>${demoDocActions("agreement","agreement summary")}<section class="agreement-hero"><div><p class="kicker">COMMERCIAL HVAC MAINTENANCE</p><h2>BMW of Coconut Creek</h2><p>Version 1 · Issued October 8, 2026 · Proposal validity: 30 days</p></div><span class="badge sent">Pending review</span></section><section class="terms-grid"><article><small>Portfolio investment</small><strong>$28,512</strong><span>$2,376 / month</span></article><article><small>Standalone proposal</small><strong>$32,400</strong><span>$2,700 / month</span></article><article><small>Scheduled coverage</small><strong>04</strong><span>Rounds per year</span></article><article><small>Portfolio advantage</small><strong>20.8%</strong><span>$7,488 projected savings</span></article></section><section class="split"><article class="panel"><h3>Included program framework</h3><ul class="premium-list"><li>Four planned preventive-maintenance rounds</li><li>Proposal-version and decision tracking</li><li>Condition reporting with photographic findings</li><li>Service scheduling and closeout visibility</li></ul></article><article class="panel"><h3>Proposal document</h3><p class="lede">Review the exact supplied document attached to this location.</p><div class="actions"><button type="button" class="button primary" data-view="proposal-bmw-coconut-creek-v1">View proposal</button><button type="button" class="button" data-download="proposal-bmw-coconut-creek-v1">Download PDF</button></div></article></section>`}
function coconutUpcoming(){const items=state.services.filter(s=>s.locationId==="bmw-coconut-creek");return `<div class="section-title"><h2>Upcoming service</h2><span>Demo schedule</span></div>${demoDocActions("upcoming","work order PDF")}<section class="visit-card"><div class="visit-date"><strong>22</strong><span>OCT<br>2026</span></div><div><p class="kicker">ROUND 01 · PREVENTIVE MAINTENANCE</p><h2>Site readiness visit</h2><p>8:00 AM–12:00 PM · Technician assignment pending</p></div><span class="badge sent">Proposed</span></section><section class="split"><article class="panel"><h3>Planned field sequence</h3><ol class="sequence"><li><b>01</b><span>Arrival and site coordination<small>Confirm access, safety requirements and priority areas.</small></span></li><li><b>02</b><span>Equipment assessment<small>Document operating condition and baseline readings.</small></span></li><li><b>03</b><span>Preventive service<small>Complete proposal-aligned maintenance checklist.</small></span></li><li><b>04</b><span>Digital closeout<small>Publish findings, photographs and recommendations.</small></span></li></ol></article><article class="panel"><h3>Visit readiness</h3><div class="readiness"><span><i class="done"></i>Location confirmed</span><span><i class="done"></i>Scope attached</span><span><i></i>Primary contact assignment</span><span><i></i>Technician assignment</span></div></article></section>${items.length?`<div class="panel compact-services">${serviceRows(items)}</div>`:""}`}
function coconutHistory(){return `<div class="section-title"><h2>Service history</h2><span>Sample records · No actual work represented</span></div>${demoDocActions("history","service history PDF")}<section class="history-ledger"><article><time>OCT 08<br>2026</time><div><span class="badge viewed">Documented</span><h3>Maintenance proposal issued</h3><p>OB-PM-2026-1008-01 · Version 1 added to the location workspace.</p></div><b>Proposal</b></article><article><time>OCT 10<br>2026</time><div><span class="badge">Sample</span><h3>Portfolio review prepared</h3><p>Commercial terms and four-round maintenance structure staged for review.</p></div><b>Planning</b></article><article><time>OCT 22<br>2026</time><div><span class="badge sent">Proposed</span><h3>First preventive-maintenance round</h3><p>Demonstration appointment only. No service completion is claimed.</p></div><b>Upcoming</b></article></section>`}
function coconutPanel(tab){if(tab==="equipment")return coconutEquipment();if(tab==="condition")return coconutCondition();if(tab==="agreement")return coconutAgreement();if(tab==="upcoming")return coconutUpcoming();if(tab==="history")return coconutHistory();return coconutOverview()}
function conditionLocationOverview(l){return `<section class="location-summary"><article class="score-card condition-account"><p class="kicker">CONDITION REPORT</p><strong>${l.conditionReport.metric.split(" ")[0]}</strong><span>${l.conditionReport.metric.replace(/^\S+\s*/,"")}</span><div class="score-track"><i style="width:100%"></i></div></article><article class="panel executive"><span class="badge viewed">Documents available</span><h2>${l.conditionReport.title}</h2><p>${l.conditionReport.summary}</p><div class="mini-metrics"><span><b>${l.conditionReport.date}</b>Report date</span><span><b>PDF</b>Proposal and condition report</span><span><b>O'Brien AC</b>Prepared for ${l.name}</span></div></article></section><div class="section-title"><h2>Location documents</h2><span>Proposal and condition-report workspace</span></div><section class="feature-grid condition-feature"><button data-location-tab="proposal"><span>01</span><strong>Proposal</strong><small>Review scope, pricing, options and authorization terms</small></button><button data-location-tab="condition"><span>02</span><strong>Condition Reports</strong><small>Review findings, photographs and recommended priorities</small></button><button data-condition-open="${l.id}"><span>03</span><strong>Open condition report</strong><small>Open the complete field report in a separate browser tab</small></button></section>`}
function proposalDocumentPanel(l){const p=l.proposalDocument;return `<div class="section-title"><h2>Proposal</h2><span>${p.reference} · ${p.date}</span></div><section class="report-hero proposal-document"><div><p class="kicker">${l.brand}</p><h2>${p.title}</h2><p>${p.summary}</p><div class="actions"><button type="button" class="button primary" data-location-proposal-view="${l.id}">View proposal</button><button type="button" class="button" data-location-proposal-open="${l.id}">Open PDF</button><button type="button" class="button" data-location-proposal-download="${l.id}">Download</button></div></div><div class="proposal-value"><small>Proposal investment</small><strong>${p.metric}</strong><span>${p.detail}</span></div></section><div class="notice">This is the supplied proposal for ${l.name}. Review the complete PDF for equipment schedules, inclusions, exclusions, validity and authorization terms.</div>`}
function plansPanel(l){const p=l.plans;return `<div class="section-title"><h2>Plans</h2><span>${p.date}</span></div><section class="report-hero"><div><p class="kicker">${l.brand}</p><h2>${p.title}</h2><p>${p.summary}</p><div class="actions"><a class="button primary" href="${p.url}" target="_blank" rel="noopener">Open plans</a><a class="button" href="${p.url}" download>Download PDF</a></div></div><div class="health-ring report-count"><strong>${p.metric.split(" ")[0]}</strong><span>${p.metric.replace(/^\S+\s*/,"")}</span></div></section><section class="panel plan-viewer"><iframe src="${p.url}" title="${l.name} electrical plans"></iframe></section><div class="notice">This is the supplied electrical plan set for ${l.name}. Use the complete PDF for sheet-level detail, notes, symbols and dimensions.</div>`}
function wirePlansActions(){}
function conditionReportPanel(l){return `<div class="section-title"><h2>Condition report</h2><span>${l.conditionReport.date}</span></div><section class="report-hero"><div><p class="kicker">${l.brand}</p><h2>${l.conditionReport.title}</h2><p>${l.conditionReport.summary}</p><div class="actions"><button type="button" class="button primary" data-condition-view="${l.id}">View report</button><button type="button" class="button" data-condition-open="${l.id}">Open PDF</button><button type="button" class="button" data-condition-download="${l.id}">Download</button></div></div><div class="health-ring report-count"><strong>${l.conditionReport.metric.split(" ")[0]}</strong><span>${l.conditionReport.metric.replace(/^\S+\s*/,"")}</span></div></section><div class="notice">This is the supplied field condition report for ${l.name}. Review the complete PDF for photographs, unit-level findings, limitations and recommended corrective action.</div>`}
function genericLocationPanel(tab,l){if(tab==="proposal")return l.proposalDocument?proposalDocumentPanel(l):proposalsView(l.id);if(tab==="plans"&&l.plans)return plansPanel(l);if(tab==="condition"&&l.conditionReport)return conditionReportPanel(l);if(tab==="upcoming")return `<div class="section-title"><h2>Upcoming services</h2><span>Location schedule</span></div><section class="panel">${serviceRows(state.services.filter(s=>s.locationId===l.id))||`<div class="empty">No demonstration appointments.</div>`}</section>`;if(l.conditionReport)return conditionLocationOverview(l);return `${proposalsView(l.id)}<section class="panel" id="services"><h3>Upcoming services</h3>${serviceRows(state.services.filter(s=>s.locationId===l.id))||`<div class="empty">No demonstration appointments.</div>`}</section>`}
function locationView(id){const l=allowedLocations().find(x=>x.id===id);if(!l)return go("#/dashboard");const elite=id==="bmw-coconut-creek",conditionAccount=Boolean(l.conditionReport),tabs=conditionAccount?`<button type="button" class="active" data-location-tab="overview">Overview</button><button type="button" data-location-tab="proposal">Proposal</button>${l.plans?`<button type="button" data-location-tab="plans">Plans</button>`:""}<button type="button" data-location-tab="condition">Condition Reports</button><button type="button" data-location-tab="upcoming">Upcoming Services</button>`:`<button type="button" class="active" data-location-tab="overview">Overview</button><button type="button" data-location-tab="equipment">Equipment</button><button type="button" data-location-tab="proposal">Proposal</button><button type="button" data-location-tab="condition">Condition Reports</button><button type="button" data-location-tab="agreement">Agreement</button><button type="button" data-location-tab="upcoming">Upcoming Services</button><button type="button" data-location-tab="history">Service History</button>`;shell(`<button type="button" class="ghost" data-go="#/dashboard">← Portfolio</button><section class="hero location-hero" ${l.photo?`style="--location-photo:url('${l.photo}')"`:""}><div>${l.logo?`<img class="location-hero-logo" src="${l.logo}" alt="${l.brand} logo">`:`<p class="kicker">${l.brand}</p>`}<h1>${l.name}</h1><p class="lede">${l.address}<br>Primary contact: awaiting customer assignment</p></div></section><div class="tabs location-tabs">${tabs}</div><section id="location-workspace">${elite?coconutPanel("overview"):genericLocationPanel("overview",l)}</section>${elite?`<p class="notice elite-notice">This elite workspace contains proposal-aligned demonstration data. Equipment, condition findings, appointments, service requests and service-history entries are samples and do not represent completed or dispatched field work.</p>`:""}`,"dashboard");document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll(".location-tabs [data-location-tab]").forEach(b=>b.onclick=()=>activateLocationTab(b.dataset.locationTab,id,elite));wireProposalActions();wireLocationTabs();wireEquipmentActions();wireDemoDocuments();wireConditionReportActions();wireLocationProposalActions();wirePlansActions()}
function activateLocationTab(tab,id,elite){document.querySelectorAll(".location-tabs button").forEach(x=>x.classList.toggle("active",x.dataset.locationTab===tab));const workspace=document.querySelector("#location-workspace"),l=LOCATIONS.find(x=>x.id===id);workspace.innerHTML=elite?(tab==="proposal"?proposalsView(id):coconutPanel(tab)):genericLocationPanel(tab,l);wireProposalActions();wireLocationTabs();wireEquipmentActions();wireDemoDocuments();wireConditionReportActions();wireLocationProposalActions();workspace.scrollIntoView({behavior:"smooth",block:"start"})}
function wireLocationTabs(){document.querySelectorAll("#location-workspace [data-location-tab]").forEach(b=>b.onclick=()=>document.querySelector(`.location-tabs [data-location-tab="${b.dataset.locationTab}"]`).click())}
