function wireDemoDocuments(){document.querySelectorAll("[data-demo-doc]").forEach(b=>b.onclick=()=>previewDemoDocument(b.dataset.demoDoc));document.querySelectorAll("[data-demo-open]").forEach(b=>b.onclick=()=>window.open(COCONUT_DOCS[b.dataset.demoOpen].url,"_blank","noopener"));document.querySelectorAll("[data-demo-download]").forEach(b=>b.onclick=()=>{const d=COCONUT_DOCS[b.dataset.demoDownload],a=document.createElement("a");a.href=d.url;a.download=d.url.split("/").pop();a.click()})}
function previewDemoDocument(key){const d=COCONUT_DOCS[key];modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card document-modal"><button type="button" class="ghost modal-close">Close</button><h2 id="modal-title">${d.name}</h2><p class="notice">Example document for demonstration purposes only.</p><iframe src="${d.url}" title="${d.name}"></iframe><div class="actions"><button type="button" class="button" data-modal-open>Open in New Tab</button><button type="button" class="button" data-modal-download>Download PDF</button></div></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("[data-modal-open]").onclick=()=>window.open(d.url,"_blank","noopener");document.querySelector("[data-modal-download]").onclick=()=>{const a=document.createElement("a");a.href=d.url;a.download=d.url.split("/").pop();a.click()}}
function wireConditionReportActions(){document.querySelectorAll("[data-condition-view]").forEach(b=>b.onclick=()=>previewConditionReport(b.dataset.conditionView));document.querySelectorAll("[data-condition-open]").forEach(b=>b.onclick=()=>{const l=LOCATIONS.find(x=>x.id===b.dataset.conditionOpen);window.open(l.conditionReport.url,"_blank","noopener")});document.querySelectorAll("[data-condition-download]").forEach(b=>b.onclick=()=>{const l=LOCATIONS.find(x=>x.id===b.dataset.conditionDownload),a=document.createElement("a");a.href=l.conditionReport.url;a.download=l.conditionReport.url.split("/").pop();a.click()})}
function previewConditionReport(id){const l=LOCATIONS.find(x=>x.id===id);modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card document-modal"><button type="button" class="ghost modal-close">Close</button><h2 id="modal-title">${l.name} · ${l.conditionReport.title}</h2><p class="notice">Complete supplied condition report with field photographs and recommendations.</p><iframe src="${l.conditionReport.url}" title="${l.name} condition report"></iframe><div class="actions"><button type="button" class="button" data-modal-open>Open in New Tab</button><button type="button" class="button" data-modal-download>Download PDF</button></div></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("[data-modal-open]").onclick=()=>window.open(l.conditionReport.url,"_blank","noopener");document.querySelector("[data-modal-download]").onclick=()=>{const a=document.createElement("a");a.href=l.conditionReport.url;a.download=l.conditionReport.url.split("/").pop();a.click()}}
function wireLocationProposalActions(){document.querySelectorAll("[data-location-proposal-view]").forEach(b=>b.onclick=()=>previewLocationProposal(b.dataset.locationProposalView));document.querySelectorAll("[data-location-proposal-open]").forEach(b=>b.onclick=()=>{const l=LOCATIONS.find(x=>x.id===b.dataset.locationProposalOpen);window.open(l.proposalDocument.url,"_blank","noopener")});document.querySelectorAll("[data-location-proposal-download]").forEach(b=>b.onclick=()=>{const l=LOCATIONS.find(x=>x.id===b.dataset.locationProposalDownload),a=document.createElement("a");a.href=l.proposalDocument.url;a.download=l.proposalDocument.url.split("/").pop();a.click()})}
function previewLocationProposal(id){const l=LOCATIONS.find(x=>x.id===id),p=l.proposalDocument;modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card document-modal"><button type="button" class="ghost modal-close">Close</button><h2 id="modal-title">${l.name} · ${p.title}</h2><p class="notice">Complete supplied proposal ${p.reference}, including scope, investment, exclusions and authorization terms.</p><iframe src="${p.url}" title="${l.name} proposal"></iframe><div class="actions"><button type="button" class="button" data-modal-open>Open in New Tab</button><button type="button" class="button" data-modal-download>Download PDF</button></div></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("[data-modal-open]").onclick=()=>window.open(p.url,"_blank","noopener");document.querySelector("[data-modal-download]").onclick=()=>{const a=document.createElement("a");a.href=p.url;a.download=p.url.split("/").pop();a.click()}}
function reportUnitModal(unitId){const unit=COCONUT_EQUIPMENT.find(x=>x.id===unitId);modal.classList.remove("hidden");modal.innerHTML=`<form class="modal-card issue-form" id="issue-report"><button type="button" class="ghost modal-close">Close</button><p class="kicker">BMW OF COCONUT CREEK · ${unit.id}</p><h2 id="modal-title">Report a unit issue</h2><p class="lede">${unit.name} · ${unit.type} · ${unit.capacity}</p><div class="notice">Demo only. Submitting this form records a sample request in this browser; it does not contact O'Brien or dispatch service.</div><label class="field">What is happening?<select name="issue" required><option value="">Select an issue</option><option>Unit is not working</option><option>Not cooling properly</option><option>Water or condensation</option><option>Unusual noise or vibration</option><option>Needs preventive service</option><option>Other service need</option></select></label><label class="field">Priority<select name="priority" required><option>Standard</option><option>Urgent</option><option>Critical - unit offline</option></select></label><label class="field">Details<textarea name="details" rows="4" placeholder="Describe what your team is seeing or hearing."></textarea></label><label class="field">Best contact<input name="contact" autocomplete="name" placeholder="Name or department" required></label><button class="button primary">Record demo request</button></form>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("#issue-report").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));state.requests=state.requests||[];state.requests.push({id:crypto.randomUUID(),locationId:"bmw-coconut-creek",unitId,...d,createdAt:new Date().toLocaleString(),status:"Open demo request"});activity(`Demo service request recorded for ${unitId}`);save();modal.classList.add("hidden");const equipmentTab=document.querySelector('.location-tabs [data-location-tab="equipment"]');if(equipmentTab)equipmentTab.click()}}
function accountManagerModal(){modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card manager-card"><button type="button" class="ghost modal-close">Close</button><p class="kicker">MORGAN AUTO GROUP</p><div class="manager-avatar">CO</div><h2 id="modal-title">Chad Oberstein</h2><p class="manager-role">Operation Manager · Assigned Account Manager</p><p class="lede">Your direct O'Brien contact for account coordination, proposal questions and service support.</p><div class="manager-contact"><a class="button primary" href="tel:+13476340943">Call (347) 634-0943</a><a class="button" href="mailto:chad@obrianac.com">Email Chad</a></div><div class="manager-details"><span><small>Direct phone</small><a href="tel:+13476340943">(347) 634-0943</a></span><span><small>Email</small><a href="mailto:chad@obrianac.com">chad@obrianac.com</a></span></div></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden")}
function dataTransferModal(){modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card transfer-card"><button type="button" class="ghost modal-close">Close</button><p class="kicker">BROWSER-LOCAL DEMO DATA</p><h2 id="modal-title">Move your demo workspace.</h2><p class="lede">Export statuses, activity, appointments, decisions and service requests from this browser, then import the JSON file on another domain or device.</p><div class="notice">Passwords and credentials are never exported. Locally selected confidential PDFs remain on this device and must be selected again.</div><div class="transfer-grid"><section><h3>Export</h3><p>Download a portable JSON snapshot of the current demonstration state.</p><button type="button" class="button primary" id="export-demo-data">Download demo data</button></section><section><h3>Import</h3><p>Choose an O'Brien portal demo JSON export. This replaces the current browser-local demo state.</p><label class="button" for="import-demo-data">Choose export file</label><input id="import-demo-data" type="file" accept="application/json,.json"><p class="error" id="transfer-error" role="alert"></p></section></div></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("#export-demo-data").onclick=exportDemoData;document.querySelector("#import-demo-data").onchange=e=>{const file=e.target.files&&e.target.files[0];if(file)importDemoData(file)}}
function serviceRows(items){return items.map(s=>`<div class="service-row"><strong>${LOCATIONS.find(l=>l.id===s.locationId).name}</strong><span>${s.type}<br><small>${s.technician}</small></span><span>${s.date}<br>${s.window}</span><span class="badge">${s.status}</span></div>`).join("")}
function capitalPlan(){const total=CAPITAL_PLAN.reduce((sum,x)=>sum+x.amount,0),urgent=CAPITAL_PLAN.filter(x=>x.priority==="Critical").reduce((sum,x)=>sum+x.amount,0),years=[...new Set(CAPITAL_PLAN.map(x=>x.year))];shell(`<section class="hero"><div><p class="kicker">FIVE-YEAR ASSET STRATEGY</p><h1>Capital plan.</h1><p class="lede">A decision-ready forecast that turns field findings into an organized replacement and reserve strategy.</p></div><div class="hero-meta"><strong>${money(total)}</strong><br>Five-year modeled plan<br><small>Demonstration estimates</small></div></section><section class="executive-strip"><article><span>Immediate priorities</span><strong>${money(urgent)}</strong><small>Proposal-backed 2026 actions</small></article><article><span>Five-year forecast</span><strong>${money(total)}</strong><small>Planned and monitored exposure</small></article><article><span>Assets modeled</span><strong>${CAPITAL_PLAN.length}</strong><small>Across ${new Set(CAPITAL_PLAN.map(x=>x.locationId)).size} locations</small></article><article><span>Planning horizon</span><strong>2030</strong><small>Rolling lifecycle outlook</small></article></section><section class="capital-layout"><div class="capital-chart panel"><div class="section-title"><h2>Investment runway</h2><span>Estimated capital by year</span></div>${years.map(year=>{const value=CAPITAL_PLAN.filter(x=>x.year===year).reduce((sum,x)=>sum+x.amount,0),width=Math.max(8,Math.round(value/urgent*100));return `<div class="capital-bar"><strong>${year}</strong><div><i style="width:${width}%"></i></div><span>${money(value)}</span></div>`}).join("")}</div><div class="panel risk-legend"><p class="kicker">PLANNING LOGIC</p><h3>Fund the critical. Stage the predictable.</h3><p>Proposal-backed work is separated from lifecycle reserves so ownership can distinguish immediate decisions from long-range planning.</p><span><i class="critical"></i> Critical · proposal or documented finding</span><span><i class="soon"></i> Plan soon · validate during upcoming service</span><span><i></i> Monitor · reserve placeholder</span></div></section><div class="section-title"><h2>Asset roadmap</h2><span>Priority, timing and decision status</span></div><section class="roadmap">${CAPITAL_PLAN.map(item=>{const l=LOCATIONS.find(x=>x.id===item.locationId);return `<article><time>${item.year}</time><div><span class="badge ${item.priority==="Critical"?"sent":""}">${item.priority}</span><h3>${item.asset}</h3><p>${l.name} · ${item.status}</p></div><strong>${money(item.amount)}</strong><button class="button" data-go="#/location/${item.locationId}">Open location</button></article>`}).join("")}</section><p class="notice">Capital values are demonstration planning figures. Final budgets require field verification, approved scope and current pricing.</p>`,"capital")}
function executiveReport(){const locs=allowedLocations(),health=Math.round(locs.reduce((sum,l)=>sum+LOCATION_INTELLIGENCE[l.id].score,0)/locs.length),openRequests=(state.requests||[]).length;shell(`<section class="report-cover"><div><p class="kicker">Q4 2026 · EXECUTIVE FACILITY BRIEF</p><h1>Comfort systems.<br><em>Business clarity.</em></h1><p>Prepared for Morgan Automotive Group by O'Brien Air Conditioning.</p></div><div class="report-mark"><span>Portfolio health</span><strong>${health}</strong><small>Demonstration index</small></div></section><section class="report-summary"><article><span>Locations represented</span><strong>${locs.length}</strong></article><article><span>Priority locations</span><strong>2</strong></article><article><span>Open service requests</span><strong>${openRequests}</strong></article><article><span>Next planned visit</span><strong>Oct 22</strong></article></section><section class="briefing-grid"><article class="briefing-card featured"><p class="kicker">EXECUTIVE RECOMMENDATION</p><h2>Authorize the documented priorities, then validate the 2027 reserve during scheduled maintenance.</h2><p>Immediate attention remains centered on Arrigo Sawgrass replacement scope and Arrigo Margate drainage corrections. The remaining portfolio is positioned for planned preventive care and lifecycle verification.</p><div class="actions"><button class="button primary" data-go="#/capital">Review capital plan</button><button class="button" data-go="#/proposals">Review proposals</button></div></article><article class="briefing-card"><p class="kicker">RISK DISTRIBUTION</p><div class="risk-donut"><strong>78%</strong><span>Portfolio operational</span></div><ul class="executive-list"><li><b>7</b> operational or monitor locations</li><li><b>2</b> action-required locations</li><li><b>${openRequests}</b> browser-local service requests</li></ul></article></section><div class="section-title"><h2>Location scorecard</h2><span>Quarterly management view</span></div><section class="scorecard-table"><div class="scorecard-row header"><span>Location</span><span>Health</span><span>Status</span><span>Exposure</span><span>Next action</span></div>${locs.map(l=>{const intel=LOCATION_INTELLIGENCE[l.id];return `<button class="scorecard-row" data-go="#/location/${l.id}"><strong>${l.name}</strong><span>${intel.score}</span><span class="status-text ${intel.tone}">${intel.status}</span><span>${intel.exposure?money(intel.exposure):"—"}</span><span>${intel.next} →</span></button>`}).join("")}</section><section class="report-footer panel"><div><p class="kicker">ACCOUNT LEADERSHIP</p><h3>Chad Oberstein · Operation Manager</h3><p>Direct coordination for service, proposals and portfolio planning.</p></div><div class="actions"><a class="button primary" href="tel:+13476340943">Call Chad</a><a class="button" href="mailto:chad@obrianac.com">Email Chad</a></div></section><p class="notice">This executive brief is a static demonstration and does not replace a signed inspection report, approved proposal or accounting record.</p>`,"report")}
function services(){const ids=allowedLocations().map(l=>l.id);shell(`<div class="section-title"><h2>Upcoming services</h2><span>Sample demonstration appointments</span></div><div class="panel">${serviceRows(state.services.filter(s=>ids.includes(s.locationId)))}</div><p class="notice">These are demonstration appointments only and are not actual bookings or completed work.</p>`,"services")}
function admin(){if(account().role!=="admin")return go("#/dashboard");shell(`<section class="hero"><div><p class="kicker">LOCAL DEMO CONTROLS</p><h1>Admin workspace.</h1><p class="lede">Changes affect only this browser. Nothing here edits GitHub files or another customer session.</p></div></section><div class="admin-tools"><section class="panel"><h3>Preview customer roles</h3><div class="actions"><button class="button" data-preview="group@demo.obrienac.com">Group manager</button><button class="button" data-preview="manager@demo.obrienac.com">Location manager</button></div></section><section class="panel"><h3>Reset demonstration</h3><p class="lede">Clear local statuses, activities and sample appointments.</p><button class="button danger" id="reset">Reset all demo data</button></section><section class="panel"><h3>Add sample appointment</h3><form id="service-form"><label class="field">Location<select name="locationId">${LOCATIONS.map(l=>`<option value="${l.id}">${l.name}</option>`).join("")}</select></label><label class="field">Date/window<input name="date" required placeholder="Jan 15, 2027 · 8–12"></label><button class="button primary">Add locally</button></form></section><section class="panel"><h3>Local document picker</h3><p class="lede">Choose a proposal or condition-report PDF without uploading it. Browser selections must be reselected on another device or after a new browser session.</p><div class="file-picker"><input id="admin-file" type="file" accept="application/pdf"><select id="admin-target">${PROPOSALS.map(p=>`<option value="${p.id}">${p.reference}</option>`).join("")}</select></div></section></div><div class="section-title"><h2>Proposal status controls</h2></div>${PROPOSALS.map(p=>`<article class="proposal"><div><h3>${LOCATIONS.find(l=>l.id===p.locationId).name}</h3><p>${p.reference}</p></div><select data-status="${p.id}">${["Draft","Sent","Viewed","Revision Requested","Accepted","Declined","Expired","Superseded"].map(s=>`<option ${state.statuses[p.id]===s?"selected":""}>${s}</option>`).join("")}</select><span class="badge">${state.statuses[p.id]}</span></article>`).join("")}`,"admin");document.querySelectorAll("[data-preview]").forEach(b=>b.onclick=()=>{state.session=b.dataset.preview;save();go("#/dashboard")});document.querySelectorAll("[data-status]").forEach(s=>s.onchange=()=>setStatus(s.dataset.status,s.value,`Admin changed demo status to ${s.value}`));document.querySelector("#reset").onclick=()=>{const session=state.session;state=baseState();state.session=session;files={};save();admin()};document.querySelector("#service-form").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));state.services.push({id:crypto.randomUUID(),locationId:d.locationId,type:"Sample preventive maintenance",date:d.date,window:"Custom window",status:"Proposed",technician:"Assignment pending",completion:"Upcoming"});activity("Sample appointment added");save();admin()};document.querySelector("#admin-file").onchange=e=>{const f=e.target.files[0];if(f)attach(document.querySelector("#admin-target").value,f)}}
function pickFile(id){const input=document.createElement("input");input.type="file";input.accept="application/pdf";input.onchange=()=>{if(input.files[0]){attach(id,input.files[0]);render()}};input.click()}
function attach(id,file){if(file.type!=="application/pdf")return alert("Please select a PDF.");if(files[id])URL.revokeObjectURL(files[id].url);files[id]={name:file.name,url:URL.createObjectURL(file)};activity(`Local PDF selected for ${PROPOSALS.find(p=>p.id===id).reference}`)}
function preview(id){const f=proposalFile(id);if(!f)return pickFile(id);modal.classList.remove("hidden");modal.innerHTML=`<div class="modal-card"><button class="ghost modal-close">Close</button><h2 id="modal-title">${cleanText(f.name,200)}</h2><p class="notice">Local browser preview — this file has not been uploaded or published.</p><iframe src="${f.url}" title="Proposal PDF preview"></iframe></div>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden")}
function setStatus(id,status,text){state.statuses[id]=status;activity(text);save();render()}
function decisionModal(id){modal.classList.remove("hidden");modal.innerHTML=`<form class="modal-card" id="decision"><button type="button" class="ghost modal-close">Close</button><h2 id="modal-title">Demonstration acceptance</h2><p class="notice">This does not create a binding agreement or notify O'Brien.</p><label class="field">Authorized name<input name="name" required></label><label class="field">Title<input name="title" required></label><label class="field"><span><input type="checkbox" name="ack" required> I acknowledge this exact proposal version for demonstration purposes.</span></label><button class="button primary">Record demo acceptance</button></form>`;document.querySelector(".modal-close").onclick=()=>modal.classList.add("hidden");document.querySelector("#decision").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));state.decisions[id]={...d,at:new Date().toISOString(),version:PROPOSALS.find(p=>p.id===id).version};state.statuses[id]="Accepted";activity(`Demo acceptance recorded for ${PROPOSALS.find(p=>p.id===id).reference}`);save();modal.classList.add("hidden");render()}}
function activity(text){state.activity.push({text,at:new Date().toLocaleString()});save()}
function render(){if(!account())return loginView();const [,route,id]=location.hash.split("/");if(route==="location")return locationView(id);if(route==="capital")return capitalPlan();if(route==="report")return executiveReport();if(route==="documents")return documents();if(route==="proposals")return proposals();if(route==="services")return services();if(route==="admin")return admin();dashboard()}
managerButton.onclick=accountManagerModal;transferButton.onclick=dataTransferModal;logout.onclick=()=>{state.session=null;save();go("#/login")};window.addEventListener("hashchange",render);render();
